/* HEXA BATTLEGROUNDS setup — PART 17 OF 20. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('recovery-keypad-503', 'keypad', 'recovery', 'Worn Keypad', 'decoding', 1, array['any']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 3, 4, 8\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from LARGEST to SMALLEST digit."},"intel":{"title":"Maintenance report","body":"The panel adds 1 to the LAST digit (9 becomes 0)."}}'::jsonb, '[{"label":"Access code","accept":["844"]}]'::jsonb, false, 5, 120, 'The code has 3 digits.', 'Ordered digits 843, after the wiring fault 844.', null, 25, 'published'), ('recovery-keypad-504', 'keypad', 'recovery', 'Worn Keypad', 'decoding', 1, array['any']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 5, 6, 8\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from SMALLEST to LARGEST digit."},"intel":{"title":"Maintenance report","body":"Enter the code in REVERSE order."}}'::jsonb, '[{"label":"Access code","accept":["865"]}]'::jsonb, false, 5, 120, 'The code has 3 digits.', 'Ordered digits 568, after the wiring fault 865.', null, 25, 'published'), ('recovery-caesar-500', 'caesar', 'recovery', 'Signal Intercept', 'decoding', 1, array['any']::text[], 'Squad 00 is broadcasting on several frequencies. Decode the genuine transmission and enter the plain word.', '{"scout":{"title":"Intercepted signals","body":"[ 104.9 MHz ]  LGRIUT\n[ 101.3 MHz ]  CTQJAP","mono":true},"decoder":{"title":"Cipher manual","body":"Every letter was pushed FORWARD along the alphabet by the key number.\nTo decode, move each letter BACKWARD by the key.\nWrap around: A moved back 1 becomes Z."},"intel":{"title":"Verified intel","body":"Genuine frequency: 104.9 MHz\nEncryption key: 6\nAll other frequencies are decoys."}}'::jsonb, '[{"label":"Decoded word","accept":["FALCON"]}]'::jsonb, false, 5, 120, 'The answer has 6 letters and starts with F.', '104.9 MHz carries LGRIUT; shifting back by 6 gives FALCON.', null, 25, 'published'), ('recovery-caesar-501', 'caesar', 'recovery', 'Signal Intercept', 'decoding', 1, array['any']::text[], 'Squad 00 is broadcasting on several frequencies. Decode the genuine transmission and enter the plain word.', '{"scout":{"title":"Intercepted signals","body":"[ 98.7 MHz ]  ALTWLZA\n[ 101.3 MHz ]  XEHYPED","mono":true},"decoder":{"title":"Cipher manual","body":"Every letter was pushed FORWARD along the alphabet by the key number.\nTo decode, move each letter BACKWARD by the key.\nWrap around: A moved back 1 becomes Z."},"intel":{"title":"Verified intel","body":"Genuine frequency: 98.7 MHz\nEncryption key: 7\nAll other frequencies are decoys."}}'::jsonb, '[{"label":"Decoded word","accept":["TEMPEST"]}]'::jsonb, false, 5, 120, 'The answer has 7 letters and starts with T.', '98.7 MHz carries ALTWLZA; shifting back by 7 gives TEMPEST.', null, 25, 'published'), ('recovery-caesar-502', 'caesar', 'recovery', 'Signal Intercept', 'decoding', 1, array['any']::text[], 'Squad 00 is broadcasting on several frequencies. Decode the genuine transmission and enter the plain word.', '{"scout":{"title":"Intercepted signals","body":"[ 98.7 MHz ]  HBYVYH\n[ 107.2 MHz ]  EHRYJQB","mono":true},"decoder":{"title":"Cipher manual","body":"Every letter was pushed FORWARD along the alphabet by the key number.\nTo decode, move each letter BACKWARD by the key.\nWrap around: A moved back 1 becomes Z."},"intel":{"title":"Verified intel","body":"Genuine frequency: 98.7 MHz\nEncryption key: 7\nAll other frequencies are decoys."}}'::jsonb, '[{"l